    this.attempts = [];
    this.fetched_text = null;
    this.fetched_pages = [];
    this.attempted_fetches = [];
    this.attempted_work_item_reads = [];
    this.failed_work_item_reads = [];
    this.search_output = null;
    this.run_outputs = [];
    this.run_observations = [];
