        const forThisUrl = fetched === url || (fetched === null && fetches === 1);
        if (forThisUrl) {
          const outcome = trim(rustLines(attempt.detail)[0] ?? '');
          lines.push(fill('read_attempt_fetch_line', [['{url}', url], ['{outcome}', outcome]]));
